def solve(inputs):
    import numpy as np

    def matrix_multiply_mod(mat1, mat2, mod):
        return np.mod(np.dot(mat1, mat2), mod)

    M = np.array([[inputs['A'], inputs['B']], [inputs['C'], inputs['D']]])
    result = M.copy()
    n = inputs['K']

    while n > 1:
        if n % 2 == 1:
            result = matrix_multiply_mod(result, M, inputs['MOD'])
        M = matrix_multiply_mod(M, M, inputs['MOD'])
        n //= 2

    return np.sum(result)

