def solve(inputs: dict) -> float:
    MOD = inputs['MOD']
    K = inputs['K']
    A, B = inputs['A'], inputs['B']
    C, D = inputs['C'], inputs['D']

    M = [[A, B], [C, D]]

    def matrix_multiply_mod(mat1, mat2, mod):
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] += (mat1[i][k] * mat2[k][j]) % mod
                result[i][j] %= mod
        return result

    def matrix_power_mod(mat, power, mod):
        result = [[1, 0], [0, 1]]  # Identity matrix
        base = mat
        while power > 0:
            if power & 1:
                result = matrix_multiply_mod(result, base, mod)
            base = matrix_multiply_mod(base, base, mod)
            power //= 2
        return result

    M_29 = matrix_power_mod(M, K, MOD)
    sum_entries = (M_29[0][0] + M_29[0][1] + M_29[1][0] + M_29[1][1]) % MOD
    return float(sum_entries)

